//! Doubly linked list node used by the ear clipping triangulator.
//!
//! The original C++ implementation links raw `Node*` pointers allocated from an
//! object pool. Here the nodes live in a single arena (`Vec<Node>`) and every
//! link is an index into that arena; `NIL` plays the role of `nullptr`.

/// Index value standing in for a null pointer.
pub const NIL: usize = usize::MAX;

#[derive(Clone, Debug)]
pub struct Node {
    /// Vertex index in the original sequence of input points.
    pub i: u32,

    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in a polygon ring.
    pub prev: usize,
    pub next: usize,

    /// z-order curve value.
    pub z: i32,

    /// Previous and next nodes in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Indicates whether this is a steiner point.
    pub steiner: bool,
}

impl Node {
    pub fn new(i: u32, x: f64, y: f64) -> Node {
        Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        }
    }
}

