//! Geometric predicates used by the triangulator.
//!
//! Every expression is written in the same order as the C++ original so that
//! floating point rounding is bit-for-bit identical.

use super::node::NIL;
use super::Earcut;

impl Earcut {
    /// Signed area of a triangle.
    #[inline]
    pub(super) fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
        (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
    }

    /// Check if two points are equal.
    #[inline]
    pub(super) fn equals(&self, p1: usize, p2: usize) -> bool {
        let (p1, p2) = (&self.nodes[p1], &self.nodes[p2]);
        p1.x == p2.x && p1.y == p2.y
    }

    #[inline]
    #[allow(clippy::too_many_arguments)]
    pub(super) fn point_in_triangle(
        &self,
        ax: f64,
        ay: f64,
        bx: f64,
        by: f64,
        cx: f64,
        cy: f64,
        px: f64,
        py: f64,
    ) -> bool {
        (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
            && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
            && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
    }

    /// Check if a diagonal between two polygon nodes is valid (lies in polygon interior).
    pub(super) fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let a_next = self.nodes[a].next;
        let a_prev = self.nodes[a].prev;
        let b_prev = self.nodes[b].prev;
        let b_next = self.nodes[b].next;
        let bi = self.nodes[b].i;

        // doesn't intersect other edges
        self.nodes[a_next].i != bi
            && self.nodes[a_prev].i != bi
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                // does not create opposite-facing sectors
                && (self.area(a_prev, a, b_prev) != 0.0 || self.area(a, b_prev, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(a_prev, a, a_next) > 0.0
                    && self.area(b_prev, b, b_next) > 0.0))
    }

    #[inline]
    pub(super) fn sign(&self, val: f64) -> i32 {
        if val > 0.0 {
            1
        } else if val < 0.0 {
            -1
        } else {
            0
        }
    }

    /// Check if two segments intersect.
    pub(super) fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = self.sign(self.area(p1, q1, p2));
        let o2 = self.sign(self.area(p1, q1, q2));
        let o3 = self.sign(self.area(p2, q2, p1));
        let o4 = self.sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        // p1, q1 and p2 are collinear and p2 lies on p1q1
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true;
        }
        // p1, q1 and q2 are collinear and q2 lies on p1q1
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true;
        }
        // p2, q2 and p1 are collinear and p1 lies on p2q2
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true;
        }
        // p2, q2 and q1 are collinear and q1 lies on p2q2
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true;
        }

        false
    }

    /// For collinear points p, q, r, check if point q lies on segment pr.
    pub(super) fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
        q.x <= fmax(p.x, r.x) && q.x >= fmin(p.x, r.x) && q.y <= fmax(p.y, r.y) && q.y >= fmin(p.y, r.y)
    }

    /// Check if a polygon diagonal intersects any polygon segments.
    pub(super) fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let ai = self.nodes[a].i;
        let bi = self.nodes[b].i;
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != ai
                && self.nodes[pn].i != ai
                && self.nodes[p].i != bi
                && self.nodes[pn].i != bi
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    /// Check if a polygon diagonal is locally inside the polygon.
    pub(super) fn locally_inside(&self, a: usize, b: usize) -> bool {
        let a_prev = self.nodes[a].prev;
        let a_next = self.nodes[a].next;
        if self.area(a_prev, a, a_next) < 0.0 {
            self.area(a, b, a_next) >= 0.0 && self.area(a, a_prev, b) >= 0.0
        } else {
            self.area(a, b, a_prev) < 0.0 || self.area(a, a_next, b) < 0.0
        }
    }

    /// Check if the middle vertex of a polygon diagonal is inside the polygon.
    pub(super) fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            let (n, nn) = (&self.nodes[p], &self.nodes[pn]);
            if ((n.y > py) != (nn.y > py))
                && nn.y != n.y
                && (px < (nn.x - n.x) * (py - n.y) / (nn.y - n.y) + n.x)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    /// Whether the sector in vertex m contains the sector in vertex p in the same coordinates.
    pub(super) fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        let m_prev = self.nodes[m].prev;
        let m_next = self.nodes[m].next;
        let p_prev = self.nodes[p].prev;
        let p_next = self.nodes[p].next;
        self.area(m_prev, m, p_prev) < 0.0 && self.area(p_next, m, m_next) < 0.0
    }

    /// Find the leftmost node of a polygon ring.
    pub(super) fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    /// Link two polygon vertices with a bridge.
    ///
    /// If the vertices belong to the same ring it splits the polygon into two; if one belongs to
    /// the outer ring and another to a hole it merges it into a single ring.
    pub(super) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.create_node(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.create_node(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Create a node and optionally link it with the previous one (in a circular doubly linked list).
    pub(super) fn insert_node(&mut self, i: usize, pt: &[f64; 2], last: usize) -> usize {
        let p = self.create_node(i as u32, pt[0], pt[1]);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let ln = self.nodes[last].next;
            self.nodes[p].next = ln;
            self.nodes[p].prev = last;
            self.nodes[ln].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    pub(super) fn remove_node(&mut self, p: usize) {
        let pn = self.nodes[p].next;
        let pp = self.nodes[p].prev;
        self.nodes[pn].prev = pp;
        self.nodes[pp].next = pn;

        let pz = self.nodes[p].prev_z;
        let nz = self.nodes[p].next_z;
        if pz != NIL {
            self.nodes[pz].next_z = nz;
        }
        if nz != NIL {
            self.nodes[nz].prev_z = pz;
        }
    }
}

/// `std::min<double>` semantics: returns `b` only when `b < a`.
#[inline]
pub(super) fn fmin(a: f64, b: f64) -> f64 {
    if b < a {
        b
    } else {
        a
    }
}

/// `std::max<double>` semantics: returns `b` only when `a < b`.
#[inline]
pub(super) fn fmax(a: f64, b: f64) -> f64 {
    if a < b {
        b
    } else {
        a
    }
}

