        let a_next = self.nodes[a].next;
        if self.area(a_prev, a, a_next) < 0.0 {
            self.area(a, b, a_next) >= 0.0 && self.area(a, a_prev, b) >= 0.0
        } else {
            self.area(a, b, a_prev) < 0.0 || self.area(a, a_next, b) < 0.0
        }
    }

    /// Check if the middle vertex of a polygon diagonal is inside the polygon.
    pub(super) fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            let (n, nn) = (&self.nodes[p], &self.nodes[pn]);
            if ((n.y > py) != (nn.y > py))
                && nn.y != n.y
                && (px < (nn.x - n.x) * (py - n.y) / (nn.y - n.y) + n.x)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    /// Whether the sector in vertex m contains the sector in vertex p in the same coordinates.
    pub(super) fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        let m_prev = self.nodes[m].prev;
        let m_next = self.nodes[m].next;
        let p_prev = self.nodes[p].prev;
        let p_next = self.nodes[p].next;
        self.area(m_prev, m, p_prev) < 0.0 && self.area(p_next, m, m_next) < 0.0
    }

    /// Find the leftmost node of a polygon ring.
    pub(super) fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    /// Link two polygon vertices with a bridge.
    ///
    /// If the vertices belong to the same ring it splits the polygon into two; if one belongs to
    /// the outer ring and another to a hole it merges it into a single ring.
    pub(super) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.create_node(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.create_node(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Create a node and optionally link it with the previous one (in a circular doubly linked list).
    pub(super) fn insert_node(&mut self, i: usize, pt: &[f64; 2], last: usize) -> usize {
        let p = self.create_node(i as u32, pt[0], pt[1]);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let ln = self.nodes[last].next;
            self.nodes[p].next = ln;
            self.nodes[p].prev = last;
            self.nodes[ln].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    pub(super) fn remove_node(&mut self, p: usize) {
        let pn = self.nodes[p].next;
        let pp = self.nodes[p].prev;
        self.nodes[pn].prev = pp;
        self.nodes[pp].next = pn;

        let pz = self.nodes[p].prev_z;
        let nz = self.nodes[p].next_z;
        if pz != NIL {
            self.nodes[pz].next_z = nz;
        }
        if nz != NIL {
            self.nodes[nz].prev_z = pz;
        }
    }
}

/// `std::min<double>` semantics: returns `b` only when `b < a`.
#[inline]
pub(super) fn fmin(a: f64, b: f64) -> f64 {
    if b < a {
        b
    } else {
        a
    }
}

/// `std::max<double>` semantics: returns `b` only when `a < b`.
#[inline]
pub(super) fn fmax(a: f64, b: f64) -> f64 {
    if a < b {
        b
    } else {
        a
    }
}

