//! A from-scratch Rust port of the `mapbox::earcut` polygon triangulator.
//!
//! Input is a polygon given as a list of rings; the first ring is the outer
//! contour, any further rings are holes. Output is a flat list of vertex index
//! triples, indexing the input points in the order they were supplied.

pub mod geom;
pub mod node;
pub mod zorder;

use geom::{fmax, fmin};
use node::{Node, NIL};

/// A ring of points; each point is `[x, y]`.
pub type Ring = Vec<[f64; 2]>;

/// A polygon: outer ring first, then holes.
pub type Polygon = [Ring];

pub struct Earcut {
    pub indices: Vec<u32>,
    vertices: usize,

    nodes: Vec<Node>,

    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

impl Default for Earcut {
    fn default() -> Self {
        Self::new()
    }
}

impl Earcut {
    pub fn new() -> Earcut {
        Earcut {
            indices: Vec::new(),
            vertices: 0,
            nodes: Vec::new(),
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    #[inline]
    pub(crate) fn create_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node::new(i, x, y));
        self.nodes.len() - 1
    }

    pub fn run(&mut self, points: &Polygon) {
        // reset
        self.indices.clear();
        self.vertices = 0;
        self.nodes.clear();

        if points.is_empty() {
            return;
        }

        let mut threshold: i32 = 80;
        let mut len: usize = 0;

        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }

        // estimate size of nodes and indices
        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NIL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later; calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.min_x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.min_y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                self.min_x = fmin(self.min_x, x);
                self.min_y = fmin(self.min_y, y);
                self.max_x = fmax(self.max_x, x);
                self.max_y = fmax(self.max_y, y);
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and size are later used to transform coords into integers for
            // z-order calculation
            self.inv_size = fmax(self.max_x - self.min_x, self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);

        self.nodes.clear();
    }

    /// Create a circular doubly linked list from polygon points in the specified winding order.
    fn linked_list(&mut self, points: &Ring, clockwise: bool) -> usize {
        let mut sum = 0.0f64;
        let len = points.len();
        let mut last = NIL;

        // calculate original winding order of a polygon ring
        let mut i = 0usize;
        let mut j = if len > 0 { len - 1 } else { 0 };
        while i < len {
            let p1 = &points[i];
            let p2 = &points[j];
            let p20 = p2[0];
            let p10 = p1[0];
            let p11 = p1[1];
            let p21 = p2[1];
            sum += (p20 - p10) * (p11 + p21);
            j = i;
            i += 1;
        }

        // link points into circular doubly-linked list in the specified winding order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, &points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, &points[i], last);
            }
        }

        if last != NIL {
            let ln = self.nodes[last].next;
            if self.equals(last, ln) {
                self.remove_node(last);
                last = ln;
            }
        }

        self.vertices += len;

        last
    }

    /// Eliminate colinear or duplicate points.
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut end = if end == NIL { start } else { end };

        let mut p = start;
        let mut again;
        loop {
            again = false;

            let pn = self.nodes[p].next;
            let pp = self.nodes[p].prev;
            if !self.nodes[p].steiner && (self.equals(p, pn) || self.area(pp, p, pn) == 0.0) {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = pn;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        if ear == NIL {
            return;
        }
        let mut ear = ear;

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let found = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if found {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                // try filtering points and slicing again
                if pass == 0 {
                    let filtered = self.filter_points(ear, NIL);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small self-intersections locally
                    let filtered = self.filter_points(ear, NIL);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon into two
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[c].next;

        while p != a {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            if self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py) {
                let pp = self.nodes[p].prev;
                let pn = self.nodes[p].next;
                if self.area(pp, p, pn) >= 0.0 {
                    return false;
                }
            }
            p = self.nodes[p].next;
        }

        true
    }

    /// Same as [`Earcut::is_ear`], but using the z-order curve index to only visit nearby points.
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = fmin(ax, fmin(bx, cx));
        let min_ty = fmin(ay, fmin(by, cy));
        let max_tx = fmax(ax, fmax(bx, cx));
        let max_ty = fmax(ay, fmax(by, cy));

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;

        while p != NIL && self.nodes[p].z <= max_z {
            if p != a && p != c {
                let (px, py) = (self.nodes[p].x, self.nodes[p].y);
                if self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py) {
                    let pp = self.nodes[p].prev;
                    let pn = self.nodes[p].next;
                    if self.area(pp, p, pn) >= 0.0 {
                        return false;
                    }
                }
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;

        while p != NIL && self.nodes[p].z >= min_z {
            if p != a && p != c {
                let (px, py) = (self.nodes[p].x, self.nodes[p].y);
                if self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py) {
                    let pp = self.nodes[p].prev;
                    let pn = self.nodes[p].next;
                    if self.area(pp, p, pn) >= 0.0 {
                        return false;
                    }
                }
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut start = start;
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let pn = self.nodes[p].next;
            let b = self.nodes[pn].next;

            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                self.remove_node(p);
                let pn2 = self.nodes[p].next;
                self.remove_node(pn2);

                p = b;
                start = b;
            }

            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// Try splitting the polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let an = self.nodes[a].next;
            let mut b = self.nodes[an].next;
            let a_prev = self.nodes[a].prev;

            while b != a_prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let an2 = self.nodes[a].next;
                    let a2 = self.filter_points(a, an2);
                    let cn = self.nodes[c].next;
                    c = self.filter_points(c, cn);

                    // run earcut on each half
                    self.earcut_linked(a2, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }

            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    /// Link every hole into the outer loop, producing a single-ring polygon without holes.
    fn eliminate_holes(&mut self, points: &Polygon, outer_node: usize) -> usize {
        let mut outer_node = outer_node;
        let len = points.len();

        let mut queue: Vec<usize> = Vec::new();
        for i in 1..len {
            let list = self.linked_list(&points[i], false);
            if list != NIL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }
        queue.sort_by(|a, b| {
            self.nodes[*a]
                .x
                .partial_cmp(&self.nodes[*b].x)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        // process holes from left to right
        for q in queue {
            outer_node = self.eliminate_hole(q, outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects a hole with an outer ring, and link it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let brn = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, brn);
        let bn = self.nodes[bridge].next;
        self.filter_points(bridge, bn)
    }

    /// David Eberly's algorithm for finding a bridge between a hole and the outer polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost vertex to the left;
        // segment's endpoint with lesser x will be potential connection vertex
        loop {
            let pn = self.nodes[p].next;
            if hy <= self.nodes[p].y && hy >= self.nodes[pn].y && self.nodes[pn].y != self.nodes[p].y
            {
                let x = self.nodes[p].x
                    + (hy - self.nodes[p].y) * (self.nodes[pn].x - self.nodes[p].x)
                        / (self.nodes[pn].y - self.nodes[p].y);
                if x <= hx && x > qx {
                    qx = x;
                    m = if self.nodes[p].x < self.nodes[pn].x { p } else { pn };
                    if x == hx {
                        // hole touches outer segment; pick leftmost endpoint
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // look for points inside the triangle of hole vertex, segment intersection and endpoint;
        // if there are no points found, we have a valid connection;
        // otherwise choose the vertex of the minimum angle with the ray as connection vertex

        let stop = m;
        let mut tan_min = f64::INFINITY;

        p = m;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;

        loop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            if hx >= px
                && px >= mx
                && hx != px
                && self.point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px);

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }
}

/// Triangulate a polygon, returning a flat list of vertex indices (three per triangle).
pub fn earcut(polygon: &Polygon) -> Vec<u32> {
    let mut e = Earcut::new();
    e.run(polygon);
    std::mem::take(&mut e.indices)
}

