//! Generation of the damped-sine "fractal" test polygon.

use crate::earcut::Ring;

/// Build the polygon used by this test: a damped sine wave sampled at `n * 2`
/// points, closed off through `(3, 0)` and `(0, 0)`.
pub fn fractal_polygon(n: i32) -> Vec<Ring> {
    let mut polygon: Vec<Ring> = Vec::new();
    let mut fractal: Ring = Vec::new();

    let count = n.wrapping_mul(2);
    let mut i: i32 = 0;
    while i < count {
        let t = f64::from(i) / f64::from(count);
        let x = t * 3.0;
        let y = (t * 10.0).sin() * (-t).exp() * 2.0 + 1.0;
        fractal.push([x, y]);
        i += 1;
    }

    fractal.push([3.0, 0.0]);
    fractal.push([0.0, 0.0]);

    polygon.push(fractal);
    polygon
}

