//! Command line handling, mirroring the C runtime helpers the original used.

/// Reimplementation of C's `std::atoi`: skip leading whitespace, accept an
/// optional sign, then consume decimal digits and stop at the first character
/// that isn't one. Anything unparseable yields `0`.
pub fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0usize;

    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c) {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value
            .saturating_mul(10)
            .saturating_add(i64::from(bytes[i] - b'0'));
        i += 1;
    }

    let signed = if negative { -value } else { value };
    signed.clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32
}

