//! Sanity checks for code paths that `test19` itself never reaches (holes).

use super::{earcut, Ring};

/// Sum of the areas of the emitted triangles.
fn triangulated_area(rings: &[Ring], indices: &[u32]) -> f64 {
    let points: Vec<[f64; 2]> = rings.iter().flat_map(|r| r.iter().copied()).collect();
    let mut total = 0.0;
    for t in indices.chunks(3) {
        let a = points[t[0] as usize];
        let b = points[t[1] as usize];
        let c = points[t[2] as usize];
        total += ((b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1])).abs() / 2.0;
    }
    total
}

#[test]
fn triangulates_a_square() {
    let square: Vec<Ring> = vec![vec![[0.0, 0.0], [4.0, 0.0], [4.0, 4.0], [0.0, 4.0]]];
    let indices = earcut(&square);
    assert_eq!(indices.len(), 6);
    assert!((triangulated_area(&square, &indices) - 16.0).abs() < 1e-12);
}

#[test]
fn triangulates_a_square_with_a_square_hole() {
    let poly: Vec<Ring> = vec![
        vec![[0.0, 0.0], [4.0, 0.0], [4.0, 4.0], [0.0, 4.0]],
        vec![[1.0, 1.0], [1.0, 3.0], [3.0, 3.0], [3.0, 1.0]],
    ];
    let indices = earcut(&poly);

    // 8 vertices, one hole => 8 triangles covering the ring minus the hole.
    assert_eq!(indices.len(), 24);
    assert!(indices.iter().all(|&i| i < 8));
    assert!((triangulated_area(&poly, &indices) - (16.0 - 4.0)).abs() < 1e-12);
}

#[test]
fn degenerate_rings_produce_no_triangles() {
    assert!(earcut(&[]).is_empty());
    assert!(earcut(&[vec![[0.0, 0.0], [1.0, 1.0]]]).is_empty());
    // fully collinear ring
    assert!(earcut(&[vec![[0.0, 0.0], [1.0, 0.0], [2.0, 0.0]]]).is_empty());
}

